    unsigned checks=0;
    bool Check(bool ok){++checks;if(!ok)std::cerr<<"RawDot contract "<<checks<<" failed\n";return ok;}
    int Digit(char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:c>='A'&&c<='F'?c-'A'+10:-1;}
    bool Word(const std::string& s,std::uint32_t& v)
    {if(s.size()!=8)return false;v=0;for(char c:s){int d=Digit(c);if(d<0)return false;v=(v<<4)|unsigned(d);}return true;}
    void ContactWord(State& s,std::size_t at,std::uint32_t w)
    {for(unsigned i=0;i!=4;++i)s.contact[at+i]=std::uint8_t(w>>(8*i));}
    std::string Pack(const State& s)
    {
        static constexpr char digits[]="0123456789abcdef";std::string out;
        auto byte=[&](std::uint8_t b){out+=digits[b>>4];out+=digits[b&15];};
        auto words=[&](const auto& a){for(auto w:a)for(unsigned i=0;i!=4;++i)byte(std::uint8_t(w>>(8*i)));};
        for(auto b:s.contact)byte(b);words(s.raw6C);words(s.raw70);words(s.raw74);words(s.raw78);words(s.raw7C);words(s.raw80);words(s.raw84);return out;
    }
    bool Decode(const std::string& line,State& s,Input& input)
    {
        std::istringstream stream(line);std::array<std::string,22> p;for(auto& t:p)if(!(stream>>t))return false;std::string extra;if(stream>>extra)return false;
        if(p[0].size()!=960)return false;std::array<std::uint8_t,480> b{};
        for(unsigned i=0;i!=480;++i){int h=Digit(p[0][i*2]),l=Digit(p[0][i*2+1]);if(h<0||l<0)return false;b[i]=std::uint8_t(h*16+l);}
        unsigned at=0;for(auto& v:s.contact)v=b[at++];
        auto words=[&](auto& a){for(auto& w:a){w=0;for(unsigned i=0;i!=4;++i)w|=std::uint32_t(b[at++])<<(8*i);}};
        words(s.raw6C);words(s.raw70);words(s.raw74);words(s.raw78);words(s.raw7C);words(s.raw80);words(s.raw84);
        if(!Word(p[1],input.scalarArgumentWord))return false;
        for(unsigned i=0;i!=3;++i)if(!Word(p[2+i],input.bodyPointWords[i]))return false;
        for(unsigned i=0;i!=3;++i)if(!Word(p[5+i],input.body2PointWords[i]))return false;
        for(unsigned i=0;i!=6;++i)if(!Word(p[8+i],input.bodyRaw8CToA0Words[i]))return false;
        for(unsigned i=0;i!=6;++i)if(!Word(p[14+i],input.body2Raw8CToA0Words[i]))return false;
        return Word(p[20],input.managerRaw7C)&&Word(p[21],input.managerRaw80);
    }
