    bool Contracts()
    {
        bool ok=true;
        for(const auto& example:examples)
        {
            State before{},out{};Input input{};Diagnostic diagnostic{};
            ok=Check(Decode(example.input,before,input))&&ok;const auto prior=Pack(before);
            ok=Check(ComputeContactTwoBodyRawDotRowForAnalysis(before,input,out,diagnostic,Profile::PcCapturedWarmFiniteRawDotNearest037F)==Result::Completed)&&ok;
            ok=Check(Pack(out)==example.expected)&&ok;ok=Check(diagnostic.rhsStoreSelected==example.storeSelected)&&ok;ok=Check(Pack(before)==prior)&&ok;
            auto alias=before;Diagnostic aliasDiagnostic{};
            ok=Check(ComputeContactTwoBodyRawDotRowForAnalysis(alias,input,alias,aliasDiagnostic,Profile::PcCapturedWarmFiniteRawDotNearest037F)==Result::Completed)&&ok;
            ok=Check(Pack(alias)==example.expected&&aliasDiagnostic.rhsStoreSelected==example.storeSelected)&&ok;
            out=before;diagnostic.rhsStoreSelected=true;
            ok=Check(ComputeContactTwoBodyRawDotRowForAnalysis(before,input,out,diagnostic)==Result::UnqualifiedProfile)&&ok;
            ok=Check(Pack(out)==prior&&diagnostic.rhsStoreSelected)&&ok;
        }
        State before{};Input input{};ok=Check(Decode(examples[0].input,before,input))&&ok;
        auto refused=[&](State b,Input i,Result expected){State output=before;Diagnostic d{true};auto old=Pack(output);auto result=ComputeContactTwoBodyRawDotRowForAnalysis(b,i,output,d,Profile::PcCapturedWarmFiniteRawDotNearest037F);return Check(result==expected)&&Check(Pack(output)==old&&d.rhsStoreSelected);};
        auto changed=before;ContactWord(changed,0,0);ok=refused(changed,input,Result::CapturedPrimaryNotAdmitted)&&ok;
        for(auto at:{0x40U,0x58U,0x88U}){changed=before;ContactWord(changed,at,at==0x58?2:at==0x88?0:1);ok=refused(changed,input,Result::FixedStateNotAdmitted)&&ok;}
        for(auto at:{0x48U,0x4CU,0x6CU,0x70U,0x74U,0x78U,0x7CU,0x80U,0x84U}){changed=before;ContactWord(changed,at,0);ok=refused(changed,input,Result::FixedStateNotAdmitted)&&ok;}
        auto contactRead=[](const State& s,unsigned at){std::uint32_t w=0;for(unsigned k=0;k!=4;++k)w|=std::uint32_t(s.contact[at+k])<<(8*k);return w;};
        changed=before;ContactWord(changed,0x4C,contactRead(before,0x48));ok=refused(changed,input,Result::FixedStateNotAdmitted)&&ok;
        changed=before;ContactWord(changed,0x70,contactRead(before,0x6C));ok=refused(changed,input,Result::FixedStateNotAdmitted)&&ok;
        for(unsigned lane=0;lane!=6;++lane){auto i=input;i.body2Raw8CToA0Words[lane]=0x7FC00001U;ok=refused(before,i,Result::OutOfDomain)&&ok;}
        for(unsigned lane=0;lane!=3;++lane){auto i=input;i.body2PointWords[lane]=0x7F800000U;ok=refused(before,i,Result::OutOfDomain)&&ok;}
        for(auto scalar:{0x3E7FFFFFU,0x40800001U}){auto i=input;i.scalarArgumentWord=scalar;ok=refused(before,i,Result::OutOfDomain)&&ok;}
        for(unsigned lane=0;lane!=6;++lane){auto i=input;i.bodyRaw8CToA0Words[lane]=0x7FC00001U;ok=refused(before,i,Result::OutOfDomain)&&ok;}
        for(auto at:{0x94U,0x98U,0xB4U,0xC0U,0xCCU}){changed=before;ContactWord(changed,at,0x7F800000U);ok=refused(changed,input,Result::OutOfDomain)&&ok;}
        auto i=input;i.managerRaw7C^=1;ok=refused(before,i,Result::ManagerProfileNotAdmitted)&&ok;
        i=input;i.managerRaw80^=1;ok=refused(before,i,Result::ManagerProfileNotAdmitted)&&ok;
        struct Guarded{std::array<std::uint32_t,4> left;State value;std::array<std::uint32_t,4> right;};
        Guarded guarded{{0xA1U,0xB2U,0xC3U,0xD4U},before,{0xE5U,0xF6U,0x17U,0x28U}};Diagnostic d{};
        ok=Check(ComputeContactTwoBodyRawDotRowForAnalysis(guarded.value,input,guarded.value,d,Profile::PcCapturedWarmFiniteRawDotNearest037F)==Result::Completed)&&ok;
        ok=Check(guarded.left==std::array<std::uint32_t,4>{0xA1U,0xB2U,0xC3U,0xD4U}&&guarded.right==std::array<std::uint32_t,4>{0xE5U,0xF6U,0x17U,0x28U})&&ok;
        return ok;
    }
