int main(int argc,char** argv)
{
    if(argc==2&&std::string(argv[1])=="--replay")
    {
        std::string line;while(std::getline(std::cin,line))
        {
            State before{},out{};Input input{};Diagnostic d{};
            if(!Decode(line,before,input)||ComputeContactTwoBodyRawDotRowForAnalysis(before,input,out,d,Profile::PcCapturedWarmFiniteRawDotNearest037F)!=Result::Completed){std::cout<<"REFUSED\n";continue;}
            std::cout<<Pack(out)<<' '<<(d.rhsStoreSelected?1:0)<<'\n';
        }
        return 0;
    }
    if(!Contracts())return 1;
    std::cout<<"ContactTwoBodyRawDotRow: "<<checks<<" contracts passed\n";return 0;
}
